							//console.log(res.data)
							this.khList = res.data							 							
						})
						.catch(err => {
							// 异常情况
							
						})
			 }, 
        getAuthKeys() {
			let sj =   JSON.parse(window.localStorage.getItem('d2admin-1.7.2'))
			let info = sj.sys.user.用户.user.info
					Query({
					tablename:'用户',
			        field:'id',
			        tj:`用户名= '${info.name}'`  //加载条件
					})
					.then(res => {
						 this.authKeys =JSON.parse(res[0].功能权限)
						 
					})
					
					.catch(err => {})
				this.uuid = this.$util.cookies.get('uuid')
				//console.log(this.uuid)
			}, 
			getTableData() {
					let tjx	
					let tj 
					//let ss 
				//if (this.authKeys.indexOf('消息通知') > -1) {
				this.loading = true
				 if(this.searchFilter.name !='' && this.searchFilter.name != null ){
					tjx =`产品ID= '${this.searchFilter.name}'`	
					tj = tjx
					}else{
						tjx = true
						tj =  tjx 
					}

					let sql =`SELECT id,产品ID, IFNULL(SUM(库存数量),0) AS 总库存 FROM 查询库存`
					Query({
							//pageSize: this.tablePage.pageSize,//每页条数 相当于layui的limit
							//currentPage: this.tablePage.currentPage, // 相当于layui的page
							limit: this.tablePage.pageSize,
							page: this.tablePage.currentPage,
							tj:tjx +`  GROUP BY 产品ID `,
							tablename:'查询库存',
							content:sql,
							field:'id',
						})
						.then(res => {
							let _this = this	
						let cpsj = _this.cplist
					    let ss = res.data.map(function(v,i) {
						let obj4 = cpsj.find(o => o.产品ID === v.产品ID); 
						delete obj4.id;
						delete obj4.日期;
						
						 return   Object.assign(v,obj4);						
						});	
						
						console.log(ss)
						console.log(this.searchFilter.disable)
						if(this.searchFilter.disable == '预警库存'){
                         let arr =  ss.filter(function(v,i){
							   if(v.预警数量 > v.总库存){
								   return v
							   }
						   })
						   this.tableData = arr
					     }else if(this.searchFilter.disable == '全部库存'){
                           this.tableData = ss
					     }
						
						this.tablePage.totalResult = res.count
						this.loading = false
							
							
						})
						.catch(err => {
							// 异常情况
							this.loading = false
						})
				//}
			   
			},
			toggleExpandMethod ({ expanded, row }) {
				  if (expanded) {
				 console.log(row.产品ID)
				 let tj = '产品ID' + "=" +  '"' + row.产品ID + '"';
				 let tjy = `库存数量 > 0`
				 Query({
							tj:tj + ' and ' + tjy,
							tablename:'查询库存',
							field:'id'
						})
						.then(res => {
						let cpsj = this.cplist
					    let ssy = res.data.map(function(v,i) {
						let obj5 = cpsj.find(o => o.产品ID === v.产品ID); 
						delete obj5.id;
						delete obj5.日期;
						
						 return   Object.assign(v,obj5);						
						});	
						console.log(ssy)
							this.childData = ssy							 							
						})
						.catch(err => {
							// 异常情况
							
						})
				  }
              return true
            }, 
