								let _this = this	
						let cpsj = _this.cplist
					    let ss = res.data.map(function(v,i) {
						let obj4 = cpsj.find(o => o.产品ID === v.产品ID); 
						delete obj4.id;
						delete obj4.日期;
						 return   Object.assign(v,obj4);						
						});	
						
						console.log(ss)	
						this.tableData2 = ss
						this.tablePage2.totalResult2 = res.count
						this.loading = false						 							
						})
						.catch(err => {
							// 异常情况
							this.loading = false
							
						})
			},
			toggleExpandMethod2 ({ expanded, row }) {
				  if (expanded) {
					  this.loading = true
				 let sjz
				 let sjy
				 let tj = '产品ID' + "=" +  '"' + row.产品ID + '"';
				 let tjy = '货位号' + "=" +  '"' + row.货位号 + '"';
				 Query({
							tj:tj + ' and ' + tjy,
							tablename:'出单',
							field:'id'
						})
						.then(res => {
						let cpsj = this.khList
					    let ssy = res.data.map(element =>  {
						let obj5 = cpsj.find(o => o.客户ID === element.客户ID); 
						delete obj5.id;
						delete obj5.日期;
						delete obj5.类型;
						
						 return   Object.assign(element,obj5,
						 {状态:element.状态 == null ? 0: element.状态 },
						 {完成:element.完成 == null ? 0: element.完成 });						
						});	

						console.log(ssy)
						
							 
                           
						
						sjz = ssy
							//this.childData = ssy							 							
						})
						.catch(err => {
